from collections import namedtuple
import re
from .base import BaseScfcErrorFixer


class _IncorrectParam(namedtuple('_IncorrectParam', ['name', 'parent_name', 'dist_name', 'current_value'])):

    @staticmethod
    def parse_from(validation_message):
        """Parses matching validation messages"""
        name = _IncorrectParam._parse_name(validation_message)
        parent_name = _IncorrectParam._parse_parent_name(validation_message)
        dist_name = validation_message.dist_name
        current_value = _IncorrectParam._parse_current_value(validation_message)
        return _IncorrectParam(name, parent_name, dist_name, current_value)

    @staticmethod
    def _parse_name(message):
        return message.text.replace('Incorrect parameter: ', '')

    @staticmethod
    def _parse_parent_name(message):
        if ' in the ' not in message.details:
            return None
        pattern = r"\ in the (.*?) \(.*\)\."
        match = re.search(pattern, message.details)
        if match is None:
            raise KeyError("can't match " + message.details)
        return match.group(1)

    @staticmethod
    def _parse_current_value(message):
        patterns = (' value (.*?) in ', ' value (.*) is out of range ', ' has incorrect parameter value \((.*)\)')
        for pattern in patterns:
            match = re.search(pattern, message.details)
            if match is not None:
                return match.group(1)
        raise KeyError("can't match " + message.details)

    def is_simple(self):
        """Returns True if this parameter is simple (has no parent list param) and False if it is complex."""
        return self.parent_name is None

    def is_complex(self):
        """Returns True if this parameter is complex (has a parent list param) and False if it is simple."""
        return not self.is_simple()


class IncorrectValueFixer(BaseScfcErrorFixer):

    def can_fix(self, validation_message):
        """This method checks the details field of the validation message. If it contains 'out of range' or
        'incorrect parameter', the method returns True; if not, the method returns False."""
        return validation_message.is_error() and \
            (' out of range ' in validation_message.details or ' incorrect parameter value ' in validation_message.details)

    def fix(self, validation_message, param_dictionary, scfc):
        """Fixes given SCFC validation error/warning in given SCFC xml using given parameter dictionary xml"""
        incorrect_param = _IncorrectParam.parse_from(validation_message)
        param_in_dictionary = self._find_param_in_dictionary(
            param_dictionary, incorrect_param.dist_name, incorrect_param.parent_name, incorrect_param.name)
        default_value = self._get_default_value(param_in_dictionary)
        self._fix_value(incorrect_param, default_value, scfc)

    def _fix_value(self, param, default_value, scfc):
        if default_value is None:
            print(param.name + ' has no default value')
        elif param.is_simple():
            scfc.find_managed_object(param.dist_name)\
                .find_param(param.name, param.current_value)\
                .value = default_value
        else:
            scfc.find_managed_object(param.dist_name)\
                .find_list_param(param.parent_name)\
                .find_param(param.name, param.current_value)\
                .value = default_value
